"""Tests for tasks_api.models."""

from __future__ import annotations

from datetime import datetime, timedelta, timezone

import pytest

from tasks_api.models import Tag, Task, TaskPriority, TaskStatus


class TestTaskStatus:
    def test_values(self):
        assert TaskStatus.PENDING.value == "pending"
        assert TaskStatus.DONE.value == "done"

    def test_str_enum(self):
        assert str(TaskStatus.PENDING) == "pending"


class TestTaskPriority:
    def test_values(self):
        assert TaskPriority.LOW.value == "low"
        assert TaskPriority.MEDIUM.value == "medium"
        assert TaskPriority.HIGH.value == "high"

    def test_order_key_high_first(self):
        assert TaskPriority.order_key(TaskPriority.HIGH) < TaskPriority.order_key(
            TaskPriority.MEDIUM
        )
        assert TaskPriority.order_key(TaskPriority.MEDIUM) < TaskPriority.order_key(
            TaskPriority.LOW
        )

    def test_order_key_all_distinct(self):
        keys = {TaskPriority.order_key(p) for p in TaskPriority}
        assert len(keys) == 3


class TestTag:
    def test_basic_creation(self):
        tag = Tag("Python")
        assert tag.name == "python"

    def test_strip_whitespace(self):
        tag = Tag("  flask  ")
        assert tag.name == "flask"

    def test_allows_hyphens_and_underscores(self):
        tag = Tag("my-tag_1")
        assert tag.name == "my-tag_1"

    def test_non_string_raises_type_error(self):
        with pytest.raises(TypeError, match="tag name must be a string"):
            Tag(123)

    def test_empty_string_raises(self):
        with pytest.raises(ValueError, match="tag name must not be empty"):
            Tag("")

    def test_whitespace_only_raises(self):
        with pytest.raises(ValueError, match="tag name must not be empty"):
            Tag("   ")

    def test_too_long_raises(self):
        with pytest.raises(ValueError, match="32 characters or fewer"):
            Tag("a" * 33)

    def test_max_length_accepted(self):
        tag = Tag("a" * 32)
        assert len(tag.name) == 32

    def test_illegal_character_raises(self):
        with pytest.raises(ValueError, match="illegal character"):
            Tag("no spaces")

    def test_special_chars_rejected(self):
        for ch in ["@", "!", "#", ".", "/"]:
            with pytest.raises(ValueError):
                Tag(f"bad{ch}tag")


class TestTask:
    def test_default_values(self):
        now = datetime.now(timezone.utc)
        task = Task(id=1, title="Do something")
        assert task.status == TaskStatus.PENDING
        assert task.priority == TaskPriority.MEDIUM
        assert task.due_at is None
        assert task.completed_at is None
        assert task.tags == []
        assert task.created_at >= now

    def test_is_overdue_no_due_date(self):
        task = Task(id=1, title="t")
        now = datetime.now(timezone.utc)
        assert task.is_overdue(now) is False

    def test_is_overdue_done_task(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", status=TaskStatus.DONE, due_at=past)
        now = datetime.now(timezone.utc)
        assert task.is_overdue(now) is False

    def test_is_overdue_past_due(self):
        past = datetime(2020, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=past)
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is True

    def test_is_overdue_future_due(self):
        future = datetime(2030, 1, 1, tzinfo=timezone.utc)
        task = Task(id=1, title="t", due_at=future)
        now = datetime(2025, 1, 1, tzinfo=timezone.utc)
        assert task.is_overdue(now) is False
